      "solution": "using UnityEngine;\n\npublic class Exercicio : MonoBehaviour\n{\n    void Start()\n    {\n        int timer = 3;\n        while (timer > 0)\n        {\n            Debug.Log(\"T-\" + timer);\n            timer--;\n        }\n    }\n}",
