// Gerador inteligente de desafio genérico contextualizado para capítulos
function generateGenericChallenge(chapterId, actionType, isCSharp = false) {
    const cChapterTopics = [
        'I/O Basico', 'Tipos Primitivos', 'Operadores Logicos', 'Condicionais if/else',
        'Switch-Case', 'Laco While', 'Laco Do-While', 'Laco For',
        'Vetores/Arrays', 'Matrizes 2D', 'Strings e Char', 'Funcoes e Escopo',
        'Valor vs Referencia', 'Ponteiros e Enderecos', 'Structs e Registros', 'Alocacao Dinamica'
    ];
    const csChapterTopics = [
        'Variaveis e Tipos', 'Operadores Aritmeticos', 'Estruturas Condicionais', 'Lacos de Repeticao',
        'Metodos e Funcoes', 'Arrays e Vetores', 'POO e Classes', 'Encapsulamento',
        'GameObjects e Transform', 'Vector3 e Movimentacao', 'Ciclo de Vida MonoBehaviour', 'Input System',
        'Fisica e Rigidbody', 'Colisoes e Triggers', 'Raycast 3D', 'Instanciacao e Prefabs',
        'Destruicao e Spawners', 'Cameras e Cinemachine', 'Iluminacao e Luzes', 'Sistemas de Particulas',
        'Audio e Efeitos Sonoros', 'UI Canvas e Textos', 'Botoes e Eventos de UI', 'Barras de Vida e Sliders',
        'NavMesh e Inteligencia Artificial', 'Animacoes e Mecanim', 'Transicao de Animacao', 'ScriptableObjects',
        'Singletons e Gerenciadores', 'Save e Load PlayerPrefs', 'Serializacao e JSON', 'Coroutines e Temporizacao',
        'Interfaces e Polimorfismo', 'Tratamento de Excecoes TryCatch', 'Otimizacao e Object Pooling', 'Cenas e SceneManager',
        'Integracao e Build', 'Polimento Final e Boss Fight'
    ];

    const topicsList = isCSharp ? csChapterTopics : cChapterTopics;
    const topic = topicsList[chapterId] || (isCSharp ? 'Desenvolvimento de Jogos em C#' : 'Programacao em C');

    if (isCSharp) {
        if (actionType === 'attack') {
            return {
                id: `cs_ch${chapterId}_gen_atk`,
                title: `Golpe Arcano — ${topic}`,
                instruction: `Execute a canalização de dano em C#: declare \`int dano = 180;\` e exiba no console usando \`Debug.Log("DANO: " + dano);\`.`,
                starterCode: `using UnityEngine;\n\npublic class Exercicio : MonoBehaviour\n{\n    void Start()\n    {\n        // [${topic}]\n        int dano = 180;\n        Debug.Log("DANO: " + dano);\n    }\n}`,
                solutionPattern: /dano\s*=\s*180[\s\S]*Debug\.Log/i,
                hint: 'int dano = 180; Debug.Log("DANO: " + dano);'
            };
        } else if (actionType === 'counter') {
            return {
                id: `cs_ch${chapterId}_gen_cnt`,
                title: `Contra-Ataque — ${topic}`,
                instruction: `Complete a condição de contra-golpe em C#: \`if (bossAtaque > 0)\`.`,
                starterCode: `using UnityEngine;\n\npublic class Exercicio : MonoBehaviour\n{\n    void Start()\n    {\n        int bossAtaque = 150;\n        if (/* condicao */)\n        {\n            Debug.Log("CONTRA-GOLPE");\n        }\n    }\n}`,
                solutionPattern: /bossAtaque\s*>\s*0/i,
                hint: 'bossAtaque > 0'
            };
        } else if (actionType === 'dodge') {
            return {
                id: `cs_ch${chapterId}_gen_ddg`,
                title: `Evasão Tática — ${topic}`,
                instruction: `Execute a esquiva ágil exibindo \`Debug.Log("ESQUIVOU");\`.`,
                starterCode: `using UnityEngine;\n\npublic class Exercicio : MonoBehaviour\n{\n    void Start()\n    {\n        Debug.Log("ESQUIVOU");\n    }\n}`,
                solutionPattern: /Debug\.Log\s*\(\s*["']ESQUIVOU/i,
                hint: 'Debug.Log("ESQUIVOU");'
            };
        } else if (actionType === 'item') {
            return {
                id: `cs_ch${chapterId}_gen_itm`,
                title: `Canalizar Item — ${topic}`,
                instruction: `Restaure a vida aumentando o HP em +120: \`hp += 120;\` e exiba com \`Debug.Log\`.`,
                starterCode: `using UnityEngine;\n\npublic class Exercicio : MonoBehaviour\n{\n    void Start()\n    {\n        int hp = 80;\n        hp += 120;\n        Debug.Log("HP: " + hp);\n    }\n}`,
                solutionPattern: /hp\s*\+=\s*120[\s\S]*Debug\.Log/i,
                hint: 'hp += 120; Debug.Log("HP: " + hp);'
            };
        } else {
            return {
                id: `cs_ch${chapterId}_gen_rev`,
                title: `Ressuscitar Aliado — ${topic}`,
                instruction: `Restaure o combatente com \`int status = 1;\` e exiba \`Debug.Log("REVIVIDO");\`.`,
                starterCode: `using UnityEngine;\n\npublic class Exercicio : MonoBehaviour\n{\n    void Start()\n    {\n        int status = 1;\n        Debug.Log("REVIVIDO");\n    }\n}`,
                solutionPattern: /status\s*=\s*1[\s\S]*Debug\.Log/i,
                hint: 'int status = 1; Debug.Log("REVIVIDO");'
            };
        }
    }

    if (actionType === 'attack') {
        return {
            id: `ch${chapterId}_gen_atk`,
            title: `Golpe Arcano — ${topic}`,
            instruction: `Execute o ataque calculando o dano crítico: declare \`int dano = 180;\` e imprima com printf.`,
            starterCode: `#include <stdio.h>\n\nint main() {\n    // [${topic}]\n    int dano = 180;\n    printf("DANO: %d\\n", dano);\n    return 0;\n}`,
            solutionPattern: /dano\s*=\s*180[\s\S]*printf/i,
            hint: 'int dano = 180; printf("DANO: %d\\n", dano);'
        };
    } else if (actionType === 'counter') {
        return {
            id: `ch${chapterId}_gen_cnt`,
            title: `Contra-Ataque — ${topic}`,
            instruction: `Complete a condição lógica para desferir o contra-ataque: \`if (bossAtaque > 0)\`.`,
            starterCode: `#include <stdio.h>\n\nint main() {\n    int bossAtaque = 150;\n    if (/* condicao */) {\n        printf("CONTRA-GOLPE\\n");\n    }\n    return 0;\n}`,
            solutionPattern: /bossAtaque\s*>\s*0/i,
            hint: 'bossAtaque > 0'
        };
    } else if (actionType === 'dodge') {
        return {
            id: `ch${chapterId}_gen_ddg`,
            title: `Evasão Tática — ${topic}`,
            instruction: `Complete a instrução de esquiva imprimindo \`ESQUIVOU\`.`,
            starterCode: `#include <stdio.h>\n\nint main() {\n    printf("ESQUIVOU\\n");\n    return 0;\n}`,
            solutionPattern: /printf\s*\(\s*["']ESQUIVOU/i,
            hint: 'printf("ESQUIVOU\\n");'
        };
    } else if (actionType === 'item') {
        return {
            id: `ch${chapterId}_gen_itm`,
            title: `Canalizar Item — ${topic}`,
            instruction: `Aplique a cura de poção aumentando o HP em +120 e exibindo com printf.`,
            starterCode: `#include <stdio.h>\n\nint main() {\n    int hp = 80;\n    hp += 120;\n    printf("HP: %d\\n", hp);\n    return 0;\n}`,
            solutionPattern: /hp\s*\+=\s*120[\s\S]*printf/i,
            hint: 'hp += 120; printf("HP: %d\\n", hp);'
        };
    } else { // revive
        return {
            id: `ch${chapterId}_gen_rev`,
            title: `Ressuscitar Aliado — ${topic}`,
            instruction: `Restaure a vida do guerreiro caído com \`int status = 1; printf("REVIVIDO\\n");\`.`,
            starterCode: `#include <stdio.h>\n\nint main() {\n    int status = 1;\n    printf("REVIVIDO\\n");\n    return 0;\n}`,
            solutionPattern: /status\s*=\s*1[\s\S]*printf/i,
            hint: 'int status = 1; printf("REVIVIDO\\n");'
        };
    }
}

class RaidChallengeManager {
    /**
     * Coleta e compõe atividades dos Capítulos com base nos assuntos de todo o intervalo
     * acumulado desde o boss anterior até o capítulo atual.
     * Exemplo: Boss 0 no cap 5 -> assuntos dos caps 0 a 5.
     *          Boss 1 no cap 10 -> assuntos dos caps 6 a 10.
     */
    static getChallenge(chapterId, actionType = 'attack') {
        const chap = Number(chapterId) || 0;
        const candidates = [];

        const isCSharp = Boolean(
            (typeof app !== 'undefined' && app.ui && typeof app.ui.isCSharpWorld === 'function' && app.ui.isCSharpWorld()) ||
            (typeof app !== 'undefined' && app.engine && app.engine.state && app.engine.state.worldId === 'csharp_unity') ||
            (typeof authManager !== 'undefined' && authManager.userData && authManager.userData.worldId === 'csharp_unity') ||
            (typeof window !== 'undefined' && window.bossRaidManager && (window.bossRaidManager.currentWorldId === 'csharp_unity' || (window.bossRaidManager.currentBoss && window.bossRaidManager.currentBoss.worldId === 'csharp_unity'))) ||
            (typeof window !== 'undefined' && window.raidRealtime && window.raidRealtime.currentRaidData && window.raidRealtime.currentRaidData.worldId === 'csharp_unity')
        );
        const worldKey = isCSharp ? 'csharp_unity' : 'c_lang';

        // Determina o intervalo cumulativo de capítulos cujos assuntos compõem este Boss
        let targetChapters = [chap];
        if (typeof BossDataManager !== 'undefined' && typeof BossDataManager.getChapterRangeForBoss === 'function') {
            const range = BossDataManager.getChapterRangeForBoss(chap, worldKey);
            if (range && Array.isArray(range.chapters) && range.chapters.length > 0) {
                targetChapters = range.chapters;
            }
        }

        const chaptersList = isCSharp && typeof CSHARP_CHAPTERS !== 'undefined' ? CSHARP_CHAPTERS : (typeof CHAPTERS !== 'undefined' ? CHAPTERS : []);

        // 1. Coleta atividades da Campanha Principal correspondentes aos assuntos do intervalo
        if (Array.isArray(chaptersList) && chaptersList.length > 0) {
            targetChapters.forEach(cId => {
                const chData = chaptersList.find(c => c.id === cId) || chaptersList[cId];
                if (chData && chData.activities && chData.activities.length > 0) {
                    const chapterSubject = chData.title || chData.theme || `Capítulo ${cId}`;
                    chData.activities.forEach(act => {
                        candidates.push({
                            id: act.id,
                            title: act.title,
                            origin: `Assunto: ${chapterSubject} (Cap. ${cId})`,
                            instruction: act.description,
                            description: act.description,
                            starterCode: act.starterCode || (isCSharp ? 'using UnityEngine;\n\npublic class Exercicio : MonoBehaviour\n{\n    void Start()\n    {\n        \n    }\n}' : '#include <stdio.h>\n\nint main() {\n    return 0;\n}'),
                            tests: act.tests || [],
                            hints: act.hints || [],
                            validator: act.validator,
                            rawActivity: act
                        });
                    });
                }
            });
        }

        // 2. Coleta atividades do Abismo para os assuntos do intervalo
        targetChapters.forEach(cId => {
            let abyssQuests = [];
            if (isCSharp) {
                if (typeof missionsManager !== 'undefined' && typeof missionsManager.getAbyssFloor === 'function') {
                    abyssQuests = missionsManager.getAbyssFloor(cId) || [];
                }
                if ((!abyssQuests || abyssQuests.length === 0) && typeof CSHARP_SIDE_QUESTS !== 'undefined') {
                    abyssQuests = CSHARP_SIDE_QUESTS[`csharp_ch${cId}`] || CSHARP_SIDE_QUESTS[cId] || [];
                }
            } else {
                if (typeof missionsManager !== 'undefined' && typeof missionsManager.getAbyssFloor === 'function') {
                    abyssQuests = missionsManager.getAbyssFloor(cId) || [];
                } else if (typeof SIDE_QUESTS !== 'undefined') {
                    abyssQuests = SIDE_QUESTS[cId] || [];
                }
            }

            if (Array.isArray(abyssQuests) && abyssQuests.length > 0) {
                abyssQuests.forEach(quest => {
                    candidates.push({
                        id: quest.id,
                        title: quest.title,
                        origin: `Abismo • Andar ${cId}`,
                        instruction: quest.description,
                        description: quest.description,
                        starterCode: quest.starterCode || (isCSharp ? 'using UnityEngine;\n\npublic class Exercicio : MonoBehaviour\n{\n    void Start()\n    {\n        \n    }\n}' : '#include <stdio.h>\n\nint main() {\n    return 0;\n}'),
                        tests: quest.tests || [],
                        hints: quest.hints || [],
                        validator: quest.validator,
                        rawActivity: quest
                    });
                });
            }
        });

        // 3. Mini-desafios pré-definidos de raid para os capítulos do intervalo (Apenas para C, pois RAID_CHALLENGES é exclusivo em C)
        if (!isCSharp) {
            targetChapters.forEach(cId => {
                const group = RAID_CHALLENGES[cId];
                if (group && group[actionType] && group[actionType].length > 0) {
                    group[actionType].forEach(raidAct => {
                        candidates.push({
                            id: raidAct.id,
                            title: raidAct.title,
                            origin: `Boss Raid • Cap. ${cId}`,
                            instruction: raidAct.instruction,
                            description: raidAct.instruction,
                            starterCode: raidAct.starterCode || '#include <stdio.h>\n\nint main() {\n    return 0;\n}',
                            solutionPattern: raidAct.solutionPattern,
                            hints: raidAct.hint ? [{ level: 'I', text: raidAct.hint }] : [],
                            rawActivity: raidAct
                        });
                    });
                }
            });
        }

        // 4. Procedural Training System (PTS) — Geração Procedural Dinâmica focada nos assuntos do intervalo
        if (typeof PTS !== 'undefined' && PTS.generateChallenge) {
            try {
                // Sorteia um capítulo dentro do intervalo cumulativo para gerar o desafio com o assunto correspondente
                const chosenFloor = targetChapters[Math.floor(Math.random() * targetChapters.length)];
                const proceduralAct = PTS.generateChallenge(chosenFloor);
                if (proceduralAct) {
                    const procStarter = proceduralAct.starterCode || '';
                    const isProcCSharp = /using\s+UnityEngine|MonoBehaviour|Debug\.Log/.test(procStarter);
                    // Garante que o desafio procedural respeite estritamente a dimensão ativa
                    if ((isCSharp && isProcCSharp) || (!isCSharp && !isProcCSharp)) {
                        candidates.push({
                            id: proceduralAct.id,
                            title: `[PTS] ${proceduralAct.title}`,
                            origin: `Treinamento Procedural • Assuntos Cap. ${chosenFloor}`,
                            instruction: proceduralAct.description,
                            description: proceduralAct.description,
                            starterCode: proceduralAct.starterCode,
                            tests: proceduralAct.tests,
                            hints: proceduralAct.hints,
                            validator: proceduralAct.validator,
                            rawActivity: proceduralAct
                        });
                    }
                }
            } catch (e) {
                console.warn('[RaidChallengeManager] PTS generation notice:', e);
            }
        }

        // FILTRO DE SEGURANÇA ESTRITO: Elimina contaminação cruzada entre C e C# e bloqueia conteúdos posteriores ao Boss
        const maxAllowedChapter = Math.max(...targetChapters, chap);
        const filteredCandidates = candidates.filter(cand => {
            // Regra Curricular Rígida: Garante que nenhum desafio seja de capítulo futuro além do teto do boss
            if (cand.chapterId !== undefined && cand.chapterId > maxAllowedChapter) {
                return false;
            }

            const starter = cand.starterCode || '';
            const instr = (cand.instruction || '') + ' ' + (cand.description || '') + ' ' + (cand.title || '');
            const hasCIndicators = /#include\s*<stdio\.h>|printf\s*\(|scanf\s*\(/.test(starter) || /printf|scanf|#include/i.test(instr);
            const hasCSharpIndicators = /using\s+UnityEngine|MonoBehaviour|Debug\.Log/.test(starter) || String(cand.id || '').startsWith('cs_');

            if (isCSharp) {
                // No mundo C#, JAMAIS permite código com #include ou printf
                if (hasCIndicators) return false;
                // Deve possuir indicadores C# ou não possuir C
                return hasCSharpIndicators || !hasCIndicators;
            } else {
                // No mundo C, JAMAIS permite código C# com UnityEngine / MonoBehaviour
                if (hasCSharpIndicators) return false;
                return true;
            }
        });

        // Se houver candidatos filtrados cobrindo os assuntos do intervalo, sorteia um aleatório
        if (filteredCandidates.length > 0) {
            const randomIndex = Math.floor(Math.random() * filteredCandidates.length);
            const chosen = filteredCandidates[randomIndex];
            // Garante testes mínimos para exibição no terminal caso não possua
            if (!chosen.tests || chosen.tests.length === 0) {
                chosen.tests = [
                    { input: '', expected: 'Execução sem erros', description: 'Validação de sintaxe e execução' }
                ];
            }
            return chosen;
        }

        // Fallback genérico contextualizado com o assunto do capítulo sorteado no intervalo
        const fallbackChap = targetChapters[Math.floor(Math.random() * targetChapters.length)] || chap;
        return generateGenericChallenge(fallbackChap, actionType, isCSharp);
    }
}

window.RAID_CHALLENGES = RAID_CHALLENGES;
window.RaidChallengeManager = RaidChallengeManager;



/* ═══ combat-formulas.js ═══ */
/* ═══════════════════════════════════════════════════════════════
   CODE LEVELER — BOSS BATTLE RAIDS: COMBAT FORMULAS ENGINE
   Implementação estrita das fórmulas matemáticas de atributos e dano
   (Seções 14, 15 e 16 de CODE_LEVELER_BOSS_BATTLE_RAIDS.md)
   ═══════════════════════════════════════════════════════════════ */

class CombatFormulas {
    /**
     * Multiplicador de HP baseado no Code Power (Inicia em 1000 CP)
     */
    static getCodePowerHpMultiplier(codePower = 1000) {
        const cp = Number(codePower) || 1000;
        const mult = 1 + ((cp - 1000) / 10000);
        return Math.max(1, mult);
    }

    /**
     * Multiplicador de Combate baseado no Code Power (Max +50% bônus)
     */
    static getCodePowerCombatMultiplier(codePower = 1000) {
        const cp = Number(codePower) || 1000;
        const bonus = Math.min(
            Math.max((cp - 1000) / 15000, 0),
            0.50
        );
        return 1 + bonus;
    }

    /**
     * Retorna os modificadores da subclasse do jogador
     */
    static getSubclassModifiers(subclass) {
        if (!subclass || typeof SUBCLASS_RAID_MODIFIERS === 'undefined') {
            return {};
        }
        return SUBCLASS_RAID_MODIFIERS[subclass] || {};
    }

    /**
     * Calcula os atributos completos de combate de um jogador
     */
    static calculatePlayerStats(playerData, avatarData) {
        const level = Math.max(1, Number(playerData.level) || 1);
        const codePower = Math.max(100, Number(playerData.codePower) || 1000);
        const subclass = playerData.subclass || null;
        const subMods = this.getSubclassModifiers(subclass);

        const baseHp = (avatarData && avatarData.baseHp) || 1200;
        const baseAttack = (avatarData && avatarData.baseAttack) || 105;
        const baseDefense = (avatarData && avatarData.baseDefense) || 90;
        const baseSpeed = (avatarData && avatarData.baseSpeed) || 100;

        const cpHpMult = this.getCodePowerHpMultiplier(codePower);
        const cpCombatMult = this.getCodePowerCombatMultiplier(codePower);

        // Bônus de Pontos de Status Alocados (Sistema RPG: hp: 15, atk: 8, def: 6, spd: 5)
        const STAT_MULT = { hp: 15, atk: 8, def: 6, spd: 5 };
        let allocatedPts = playerData.avatarStats || playerData.allocatedPoints || null;
        const avId = (avatarData && avatarData.id) || playerData.currentAvatarId || playerData.avatarId || '02';
        if (!allocatedPts && typeof window !== 'undefined' && window.app && window.app.engine) {
            allocatedPts = window.app.engine.getAvatarStatPoints(avId);
        }
        allocatedPts = allocatedPts || { hp: 0, atk: 0, def: 0, spd: 0 };

        // Bônus de Artefatos Equipados
        let artBonuses = playerData.artifactBonuses || null;
        if (!artBonuses && typeof window !== 'undefined' && window.app && window.app.engine) {
            artBonuses = window.app.engine.getAvatarArtifactBonuses(avId);
        }
        artBonuses = artBonuses || { hp_flat: 0, hp_pct: 0, atk_flat: 0, atk_pct: 0, def_flat: 0, def_pct: 0, spd_flat: 0, spd_pct: 0 };

        // Bônus Passivos das Boss Skills conquistadas (Mundo C e C#)
        let bossSkills = playerData.bossSkillsBonuses || null;
        if (!bossSkills && typeof window !== 'undefined' && window.app && window.app.engine && typeof window.app.engine.getBossSkillsBonuses === 'function') {
            bossSkills = window.app.engine.getBossSkillsBonuses();
        }
        bossSkills = bossSkills || { hp_flat: 0, atk_pct: 0, def_pct: 0, spd_flat: 0, bossEncounterAtkPct: 0, bossEncounterDefPct: 0, raidDefPct: 0 };

        // Pontos de status adicionados
        const addedHpFromPts = (allocatedPts.hp || 0) * STAT_MULT.hp;
        const addedAtkFromPts = (allocatedPts.atk || 0) * STAT_MULT.atk;
        const addedDefFromPts = (allocatedPts.def || 0) * STAT_MULT.def;
        const addedSpdFromPts = (allocatedPts.spd || 0) * STAT_MULT.spd;

        // Bônus passivos das Boss Skills aplicados aos atributos base
        const bossHpFlat = bossSkills.hp_flat || 0;
        const bossAtkPct = (bossSkills.atk_pct || 0) + (bossSkills.bossEncounterAtkPct || 0);
        const bossDefPct = (bossSkills.def_pct || 0) + (bossSkills.raidDefPct || 0) + (bossSkills.bossEncounterDefPct || 0);
        const bossSpdFlat = bossSkills.spd_flat || 0;

        // Fórmula Oficial de HP com Artefatos, Pontos de Status e Boss Skills
        // Multiplicadores percentuais incidem sobre o valor total acumulado do avatar
        const totalFlatHp = baseHp + addedHpFromPts + (artBonuses.hp_flat || 0) + bossHpFlat;
        const effectiveBaseHp = totalFlatHp * (1 + (artBonuses.hp_pct || 0) / 100);
        const maxHp = Math.round(
            effectiveBaseHp *
            (1 + (level - 1) * 0.08) *
            cpHpMult
        );

        // Fórmula Oficial de Ataque com Artefatos, Pontos de Status e Boss Skills
        const totalFlatAtk = baseAttack + addedAtkFromPts + (artBonuses.atk_flat || 0);
        const effectiveBaseAtk = totalFlatAtk * (1 + ((artBonuses.atk_pct || 0) + bossAtkPct) / 100);
        const attack = Math.round(
            effectiveBaseAtk *
            (1 + (level - 1) * 0.055) *
            cpCombatMult *
            (subMods.damageMultiplier || 1.0)
        );

        // Fórmula Oficial de Defesa com Artefatos, Pontos de Status e Boss Skills
        const totalFlatDef = baseDefense + addedDefFromPts + (artBonuses.def_flat || 0);
        const effectiveBaseDef = totalFlatDef * (1 + ((artBonuses.def_pct || 0) + bossDefPct) / 100);
        const defense = Math.round(
            effectiveBaseDef *
            (1 + (level - 1) * 0.045) *
            cpCombatMult *
            (subMods.defenseMultiplier || 1.0)
        );

        // Fórmula Oficial de Velocidade com Artefatos, Pontos de Status e Boss Skills
        const totalFlatSpd = baseSpeed + addedSpdFromPts + (artBonuses.spd_flat || 0) + bossSpdFlat;
        const effectiveBaseSpd = totalFlatSpd * (1 + (artBonuses.spd_pct || 0) / 100);
        const speed = Math.round(
            effectiveBaseSpd +
            Math.floor(level * 0.4) +
            (subMods.speedBonus || 0)
        );

        return {
            maxHp,
            currentHp: maxHp,
            attack,
            defense,
            speed,
            codePower,
            level,
            subclass,
            subclassMods: subMods
        };
    }

    /**
     * Calcula o bônus de tempo em segundos para desafios de código e reações
     * com base no atributo Speed do avatar.
     * Fórmula balanceada: cada 10 de Speed acima de 90 concede +1.5s (limite de 15s).
     * @param {number} playerSpeed 
     * @returns {number} Tempo bônus em segundos
     */
    static getSpeedTimeBonus(playerSpeed = 100) {
        const spd = Number(playerSpeed) || 100;
        if (spd <= 90) return 0;
        const rawBonus = Math.floor((spd - 90) / 10) * 1.5;
        return Math.min(15, Math.max(0, Math.round(rawBonus)));
    }

    /**
     * Retorna o multiplicador de ataque concedido pelos Nightbloods ativos na party.
     * Cada Nightblood vivo (não DOWNED) acumula +25% de ataque para toda a party.
     * @param {Array} players - Array de jogadores com { avatarId, combatStatus }
     * @returns {number} Multiplicador (ex: 1.25 para 1 Nightblood, 1.5 para 2, etc.)
     */
    static getNightbloodPartyMultiplier(players = []) {
        if (!players || players.length === 0) return 1.0;
        const NIGHTBLOOD_AVATAR_ID = '23';
        const NIGHTBLOOD_BONUS = 0.25;
        let count = 0;
        for (const p of players) {
            if (
                p.combatStatus !== 'DOWNED' &&
                (p.currentHp || 0) > 0 &&
                p.avatarId === NIGHTBLOOD_AVATAR_ID
            ) {
                count++;
            }
        }
        return 1.0 + (count * NIGHTBLOOD_BONUS);
    }

    /**
     * Redução de dano pela defesa (Seção 15):
     * defenseReduction = defender.defense / (defender.defense + 100)
     */
    static getDefenseReduction(defense) {
        const def = Math.max(0, Number(defense) || 0);
        return def / (def + 100);
    }

    /**
     * Cálculo de Dano Final (Seção 15):
     * rawDamage = attacker.attack * skillMultiplier
     * finalDamage = Math.max(1, Math.round(rawDamage * (1 - defenseReduction)))
     */
    static calculateDamage(attacker, defender, skillMultiplier = 1.0) {
        const rawDamage = (attacker.attack || 100) * (Number(skillMultiplier) || 1.0);
        const defReduction = this.getDefenseReduction(defender.defense || 0);
        const finalDamage = Math.max(
            1,
            Math.round(rawDamage * (1 - defReduction))
        );
        return {
            rawDamage: Math.round(rawDamage),
            defenseReduction: defReduction,
            finalDamage: finalDamage
        };
    }

    /**
     * Cálculo de Cura de Item Individual (Poção de Vida):
     * Cura 45% do maxHp do usuário + bônus de subclasse (Reviewer)
     */
    static calculateHeal(user) {
        const subMods = user.subclassMods || this.getSubclassModifiers(user.subclass);
        const mult = (subMods.healMultiplier || 1.0);
        const baseHeal = (user.maxHp || 600) * 0.45;
        return Math.round(baseHeal * mult);
    }

    /**
     * Cálculo de Cura de Item Coletivo (Elixir da Party):
     * Cura 35% do maxHp de cada aliado da equipe
     */
    static calculateGroupHeal(target, user) {
        const subMods = (user && (user.subclassMods || this.getSubclassModifiers(user.subclass))) || {};
        const mult = (subMods.healMultiplier || 1.0);
        const baseHeal = (target.maxHp || 600) * 0.35;
        return Math.round(baseHeal * mult);
    }

    /**
     * Reviver jogador (Seção 8.3):
     * revivedHp = player.maxHp * 0.30 (+ bônus de subclasse Debugger)
     */
    static calculateReviveHp(downedPlayer, reviver = null) {
        let bonus = 0;
        if (reviver) {
            const mods = reviver.subclassMods || this.getSubclassModifiers(reviver.subclass);
            bonus = mods.reviveBonus || 0;
        }
        const pct = 0.30 + bonus;
        return Math.max(1, Math.round((downedPlayer.maxHp || 1000) * pct));
    }
}

window.CombatFormulas = CombatFormulas;


/* ═══ turn-engine.js ═══ */
/* ═══════════════════════════════════════════════════════════════
   CODE LEVELER — BOSS BATTLE RAIDS: TURN ENGINE (SIMULTANEOUS MODE)
   Gerenciador de Fases Alternadas Simultâneas: Party Phase vs Boss Phase
   ═══════════════════════════════════════════════════════════════ */

class TurnEngine {
    constructor() {
        this.bossEntity = null;
        this.playerEntities = [];
        this.currentPhase = 'PARTY'; // 'PARTY' ou 'BOSS'
        this.roundCount = 1;
        this.isInitialized = false;
    }

    /**
     * Inicializa os combatentes para a batalha simultânea
     */
    init(bossEntity, playerEntities = []) {
        this.bossEntity = {
            id: bossEntity.id,
            name: bossEntity.name,
            isBoss: true,
            status: 'ACTIVE',
            ref: bossEntity
        };

        this.playerEntities = playerEntities.map(p => ({
            id: p.uid || p.id,
            name: p.name || p.displayName || 'Jogador',
            photoURL: p.photoURL || `assets/avatars/avatar_${p.avatarId || '02'}.png`,
            avatarId: p.avatarId || '02',
            isBoss: false,
            status: p.combatStatus || 'ACTIVE',
            hasActedThisRound: false,
            ref: p
        }));

        this.roundCount = 1;
        this.currentPhase = 'PARTY';
        this.isInitialized = true;

        return this.getCurrentPhaseState();
    }

    /**
     * Atualiza o status de combate de uma entidade (ex: DOWNED, ACTIVE)
     */
    updateEntityStatus(entityId, newStatus) {
        if (this.bossEntity && this.bossEntity.id === entityId) {
            this.bossEntity.status = newStatus;
        }
        const p = this.playerEntities.find(e => e.id === entityId);
        if (p) {
            p.status = newStatus;
        }
    }

    /**
     * Registra que um jogador concluiu sua ação no turno da Party
     */
    markPlayerActed(playerId) {
        const p = this.playerEntities.find(e => e.id === playerId);
        if (p) {
            p.hasActedThisRound = true;
        }
    }

    /**
     * Verifica se todos os jogadores vivos já agiram na rodada
     */
    haveAllAlivePlayersActed() {
        const alivePlayers = this.playerEntities.filter(p => p.status !== 'DOWNED' && p.status !== 'DISCONNECTED');
        if (alivePlayers.length === 0) return true;
        return alivePlayers.every(p => p.hasActedThisRound);
    }

    /**
     * Reseta as flags de ação de todos os jogadores para uma nova fase da Party
     */
    resetActionsForNewRound() {
        this.playerEntities.forEach(p => {
            p.hasActedThisRound = false;
        });
    }

    /**
     * Avança para a próxima fase (PARTY -> BOSS -> Próxima Rodada / PARTY)
     */
    advancePhase() {
        if (this.currentPhase === 'PARTY') {
            this.currentPhase = 'BOSS';
        } else {
            this.currentPhase = 'PARTY';
            this.roundCount++;
            // Reseta flags de ação para a nova rodada
            this.resetActionsForNewRound();
        }
        return this.getCurrentPhaseState();
    }

    /**
     * Retorna o estado atual da fase
     */
    getCurrentPhaseState() {
        return {
            phase: this.currentPhase,
            round: this.roundCount,
            isPartyPhase: this.currentPhase === 'PARTY',
            isBossPhase: this.currentPhase === 'BOSS',
            boss: this.bossEntity,
            players: this.playerEntities
        };
    }

    /**
     * Retorna uma representação de timeline de fases para a UI
     */
    previewTimeline(count = 5) {
        const timeline = [];
        let phase = this.currentPhase;
        let round = this.roundCount;

        for (let i = 0; i < count; i++) {
            if (phase === 'PARTY') {
                timeline.push({
                    id: `party_r${round}`,
                    name: `Party (Rodada ${round})`,
                    isBoss: false,
                    phase: 'PARTY',
                    round
                });
                phase = 'BOSS';
            } else {
                timeline.push({
                    id: `boss_r${round}`,
                    name: `${this.bossEntity ? this.bossEntity.name : 'Boss'}`,
                    isBoss: true,
                    phase: 'BOSS',
                    round
                });
                phase = 'PARTY';
                round++;
            }
        }
        return timeline;
    }
}

window.TurnEngine = TurnEngine;


/* ═══ boss-ai.js ═══ */
/* ═══════════════════════════════════════════════════════════════
   CODE LEVELER — BOSS BATTLE RAIDS: BOSS AI & TARGETING
   Seleção de ações do chefe e alvos (Seção 10 de CODE_LEVELER_BOSS_BATTLE_RAIDS.md)
   ═══════════════════════════════════════════════════════════════ */

class BossAI {
    /**
     * Sorteia o tipo de ação do Boss com base nos pesos configuráveis
     */
    static selectActionType(actionWeights = null) {
        const weights = actionWeights || BOSS_ACTION_WEIGHTS;
        const rand = Math.random();

        const singleWeight = weights.SINGLE_TARGET ?? 0.50;
        const multiWeight = weights.MULTI_TARGET ?? 0.35;

        if (rand < singleWeight) {
            return 'SINGLE_TARGET';
        } else if (rand < singleWeight + multiWeight) {
            return 'MULTI_TARGET';
        } else {
            return 'AOE';
        }
    }

    /**
     * Seleciona alvos vivos (ACTIVE / TARGETED) entre os jogadores
     */
    static chooseTargets(actionType, alivePlayers = []) {
        if (!alivePlayers || alivePlayers.length === 0) {
            return [];
        }

        // Embaralha jogadores vivos para seleção aleatória justa
        const shuffled = [...alivePlayers].sort(() => Math.random() - 0.5);

        if (actionType === 'SINGLE_TARGET' || alivePlayers.length === 1) {
            return [shuffled[0]];
        } else if (actionType === 'MULTI_TARGET') {
            const count = Math.min(alivePlayers.length, Math.random() < 0.6 ? 2 : 3);
            return shuffled.slice(0, count);
        } else { // AOE
            return [...alivePlayers];
        }
    }

    /**
     * Decide o ataque completo do Boss
     */
    static decideAttack(boss, players = []) {
        // Filtra APENAS jogadores verdadeiramente vivos (com HP > 0 e que não estejam caídos)
        const alive = players.filter(p => {
            const hp = p.currentHp !== undefined ? p.currentHp : (p.baseHp || 1200);
            return hp > 0 && p.combatStatus !== 'DOWNED' && p.combatStatus !== 'DISCONNECTED';
        });

        if (alive.length === 0) return null;

        const actionType = this.selectActionType(boss.actionWeights);
        const targets = this.chooseTargets(actionType, alive);

        let multiplier = 1.0;
        if (actionType === 'SINGLE_TARGET') {
            multiplier = boss.singleTargetMultiplier || 1.0;
        } else if (actionType === 'MULTI_TARGET') {
            multiplier = boss.multiTargetMultiplier || 0.80;
        } else {
            multiplier = boss.aoeMultiplier || 0.65;
        }

        const targetUids = targets.map(t => t.uid || t.id);

        return {
            actionType,
            multiplier,
            targetUids
        };
    }
}

window.BossAI = BossAI;


/* ═══ raid-challenge-engine.js ═══ */
/* ═══════════════════════════════════════════════════════════════
   CODE LEVELER — BOSS BATTLE RAIDS: CHALLENGE VALIDATION ENGINE
   Validação rápida de código no editor, temporizador e resolução HIT / MISS
   ═══════════════════════════════════════════════════════════════ */

class RaidChallengeEngine {
    constructor() {
        this.currentChallenge = null;
        this.currentActionType = null;
        this.timerSeconds = 0;
        this.timerInterval = null;
        this.onTickCallback = null;
        this.onTimeoutCallback = null;
    }

    /**
     * Inicia um desafio com contagem regressiva
     */
    startChallenge(chapterId, actionType, onTick, onTimeout) {
        this.stopTimer();
        this.currentActionType = actionType;
        this.currentChallenge = RaidChallengeManager.getChallenge(chapterId, actionType);
        this.onTickCallback = onTick;
        this.onTimeoutCallback = onTimeout;

        return this.currentChallenge;
    }

    stopTimer() {
        if (this.timerInterval) {
            clearInterval(this.timerInterval);
            this.timerInterval = null;
        }
    }

    /**
     * Valida o código submetido pelo jogador
     * Retorna { success: boolean, status: 'HIT' | 'MISS', reason?: string, testResults?: Array }
     */
    validateSubmission(code) {
        this.stopTimer();
        if (!this.currentChallenge) {
            return { success: false, status: 'MISS', reason: 'Nenhum desafio ativo.' };
        }

        const cleanCode = (code || '').trim();
        if (!cleanCode) {
            return { success: false, status: 'MISS', reason: 'Código em branco.' };
        }

        // 1. Validação com MissionValidator caso haja testes ou rawActivity
        if (typeof MissionValidator !== 'undefined' && this.currentChallenge.tests && this.currentChallenge.tests.length > 0) {
            try {
                const validator = new MissionValidator();
                const validation = validator.validateActivity(cleanCode, this.currentChallenge.rawActivity || this.currentChallenge);
                if (validation.pass) {
                    return { success: true, status: 'HIT', challenge: this.currentChallenge, validation };
                }
            } catch (e) {
                console.warn('Raid challenge validation error:', e);
            }
        }

        // 2. Validação direta pela função validator da atividade
        if (typeof this.currentChallenge.validator === 'function') {
            try {
                let output = '';
                const isCSharp = (typeof app !== 'undefined' && app.ui && typeof app.ui.isCSharpWorld === 'function' && app.ui.isCSharpWorld(cleanCode)) ||
                                 (typeof app !== 'undefined' && app.engine && app.engine.state && app.engine.state.worldId === 'csharp_unity') ||
                                 (typeof authManager !== 'undefined' && authManager.userData && authManager.userData.worldId === 'csharp_unity') ||
                                 (this.currentChallenge && String(this.currentChallenge.id || '').startsWith('cs_')) ||
                                 (/using\s+UnityEngine|MonoBehaviour|Debug\.Log/.test(cleanCode));

                if (isCSharp && typeof window !== 'undefined' && typeof window.CSharpInterpreter === 'function') {
                    const csInterp = new window.CSharpInterpreter();
                    const r = csInterp.execute(cleanCode);
                    output = Array.isArray(r.output) ? r.output.join('\n') : String(r.output || '');
                } else if (typeof CInterpreter !== 'undefined') {
                    const interp = new CInterpreter();
                    const testIn = (this.currentChallenge.tests && this.currentChallenge.tests[0]) ? this.currentChallenge.tests[0].input : '';
                    const r = interp.execute(cleanCode, testIn);
                    output = r.output || '';
                }
                const vRes = this.currentChallenge.validator(cleanCode, output);
                if (vRes && (vRes.pass || vRes.valid)) {
                    return { success: true, status: 'HIT', challenge: this.currentChallenge };
                }
            } catch (e) {}
        }

        // 3. Validação pelo padrão regex da solução do desafio
        if (this.currentChallenge.solutionPattern) {
            const pass = this.currentChallenge.solutionPattern.test(cleanCode);
            if (pass) {
                return { success: true, status: 'HIT', challenge: this.currentChallenge };
            }
        }

        // 4. Fallback de validação com testes estruturais da atividade caso ainda não tenha resolvido
        if (this.currentChallenge.tests && this.currentChallenge.tests.length > 0) {
            const isCSharpFallback = (typeof app !== 'undefined' && app.ui && typeof app.ui.isCSharpWorld === 'function' && app.ui.isCSharpWorld(cleanCode)) ||
                                     (typeof app !== 'undefined' && app.engine && app.engine.state && app.engine.state.worldId === 'csharp_unity') ||
                                     (typeof authManager !== 'undefined' && authManager.userData && authManager.userData.worldId === 'csharp_unity') ||
                                     (this.currentChallenge && String(this.currentChallenge.id || '').startsWith('cs_')) ||
                                     (/using\s+UnityEngine|MonoBehaviour|Debug\.Log/.test(cleanCode));

            if (isCSharpFallback && typeof window !== 'undefined' && typeof window.CSharpInterpreter === 'function') {
                try {
                    const csInterp = new window.CSharpInterpreter();
                    const execResult = csInterp.execute(cleanCode);
                    const outputStr = Array.isArray(execResult.output) ? execResult.output.join('\n') : String(execResult.output || '');
                    const exp = this.currentChallenge.tests[0]?.expected || '';
                    if ((!execResult.errors || execResult.errors.length === 0) && outputStr.includes(exp) && exp.length > 0) {
                        return { success: true, status: 'HIT', challenge: this.currentChallenge };
                    }
                } catch (e) {}
            } else if (typeof CInterpreter !== 'undefined') {
                try {
                    if (cleanCode.includes('main') && (cleanCode.includes('{') && cleanCode.includes('}'))) {
                        const interp = new CInterpreter();
                        const testIn = this.currentChallenge.tests[0]?.input || '';
                        const execResult = interp.execute ? interp.execute(cleanCode, testIn) : interp.run(cleanCode, testIn);
                        const exp = this.currentChallenge.tests[0]?.expected || '';
                        if ((!execResult.errors || execResult.errors.length === 0) && (execResult.output || '').includes(exp) && exp.length > 0) {
                            return { success: true, status: 'HIT', challenge: this.currentChallenge };
                        }
                    }
                } catch (e) {}
            }
        }

        return {
            success: false,
            status: 'MISS',
            reason: 'A saída ou sintaxe não corresponde ao objetivo da ação.',
            challenge: this.currentChallenge
        };
    }
}

window.RaidChallengeEngine = RaidChallengeEngine;



/* ═══ raid-realtime.js ═══ */
/* ═══════════════════════════════════════════════════════════════
   CODE LEVELER — BOSS BATTLE RAIDS: REALTIME SYNC SERVICE
   Gerenciamento de salas, validação de Party, Ready System e Firestore
   (Seções 4, 5, 24 e 26 de CODE_LEVELER_BOSS_BATTLE_RAIDS.md)
   ═══════════════════════════════════════════════════════════════ */

class RaidRealtimeService {
    constructor() {
        this.currentRaidId = null;
        this.currentRaidData = null;
        this.unsubRaidListener = null;
        this.onRaidUpdateCallback = null;
        this.isHost = false;
        this.localMode = false;
    }

    /**
     * Gera ID único de sala de raid para uma party ou guilda e capítulo
     */
     generateRaidId(partyId, guildCode, chapterId, uid = null) {
        if (partyId) {
            return `raid_party_${partyId}_ch${chapterId}`;
        }
        if (guildCode) {
            return `raid_guild_${guildCode}_ch${chapterId}`;
        }
        return `raid_solo_${(uid || 'anon').substring(0, 6)}_ch${chapterId}`;
    }

    /**
     * Cria ou entra em uma sala de Raid no Firestore com Transação Atômica
     */
    async joinOrCreateRaidRoom(party, chapterId, currentPlayerData, bossData, guildCode = null) {
        const uid = currentPlayerData.uid;
        const partyId = party ? party.id : null;
        const raidId = this.generateRaidId(partyId, guildCode, chapterId, uid);
        this.currentRaidId = raidId;
        console.log(`[RaidRealtime] Conectando à sala: ${raidId} (Party: ${partyId}, Guild: ${guildCode})`);

        // Se fbDB não estiver disponível, entra em modo local resiliente
        if (typeof fbDB === 'undefined') {
            this.localMode = true;
            this.isHost = true;
            this.currentRaidData = this._createLocalRoomData(raidId, partyId, chapterId, currentPlayerData, bossData);
            return this.currentRaidData;
        }

        try {
            const raidRef = fbDB.collection('raids').doc(raidId);

            // Usa runTransaction para garantir atomicidade no Firestore
            const resultData = await fbDB.runTransaction(async (transaction) => {
                const doc = await transaction.get(raidRef);

                if (!doc.exists) {
                    const initialData = this._createLocalRoomData(raidId, partyId, chapterId, currentPlayerData, bossData);
                    transaction.set(raidRef, initialData);
                    return { data: initialData, isHost: true };
                }

                const data = doc.data();
                const isFinished = data.status === 'VICTORY' || data.status === 'DEFEAT' || data.status === 'FINISHED';
                const isStale = (Date.now() - (data.createdAt || 0)) > 3600000;

                if (isFinished || isStale) {
                    const initialData = this._createLocalRoomData(raidId, partyId, chapterId, currentPlayerData, bossData);
                    transaction.set(raidRef, initialData);
                    return { data: initialData, isHost: true };
                }

                const players = [...(data.players || [])];
                const existingIndex = players.findIndex(p => p.uid === uid);
                const isBattleActive = data.status && data.status !== 'LOBBY' && data.status !== 'COUNTDOWN';

                const getSafeAvatar = (pData) => {
                    const avId = pData.avatarId || '02';
                    if (pData.photoURL && pData.photoURL.startsWith('assets/avatars/')) return pData.photoURL;
                    return `assets/avatars/avatar_${avId}.png`;
                };

                const safePlayerData = {
                    ...currentPlayerData,
                    photoURL: getSafeAvatar(currentPlayerData)
                };

                // Indica se este jogador está reingressando no meio de uma batalha
                const isRejoin = isBattleActive && existingIndex >= 0;

                if (existingIndex >= 0) {
                    const existingPlayer = players[existingIndex];
                    const safeExistingAvatar = getSafeAvatar(existingPlayer);
                    players[existingIndex] = {
                        ...existingPlayer,
                        ...safePlayerData,
                        photoURL: safePlayerData.photoURL || safeExistingAvatar,
                        // Se a batalha já estiver em andamento, mantém o HP e status de combate que ele já tinha
                        currentHp: isBattleActive && existingPlayer.currentHp !== undefined ? existingPlayer.currentHp : (safePlayerData.currentHp || safePlayerData.baseHp || 1200),
                        combatStatus: isBattleActive && existingPlayer.combatStatus ? existingPlayer.combatStatus : 'ACTIVE',
                        damageDealt: existingPlayer.damageDealt || 0,
                        damageTaken: existingPlayer.damageTaken || 0,
                        healingDone: existingPlayer.healingDone || 0,
                        revivesCount: existingPlayer.revivesCount || 0,
                        successfulActions: existingPlayer.successfulActions || 0,
                        lastActive: Date.now()
                    };
                } else if (players.length < 4) {
                    players.push({
                        ...safePlayerData,
                        currentHp: safePlayerData.currentHp || safePlayerData.baseHp || 1200,
                        ready: false,
                        combatStatus: 'ACTIVE',
                        lastActive: Date.now(),
                        damageDealt: 0,
                        damageTaken: 0,
                        healingDone: 0,
                        revivesCount: 0,
                        successfulActions: 0
                    });
                } else {
                    throw new Error('A sala da raid atingiu o limite de 4 jogadores.');
                }

                const updatedData = {
                    ...data,
                    players,
                    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                };

                // Se reingressou no meio de uma batalha ativa, garante que o jogador
                // não bloqueie a progressão do turno — injeta ação de 'rejoin' (timeout)
                // em partyActions e playerReactions caso ainda não tenha agido.
                const updatePayload = {
                    players,
                    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                };

                if (isRejoin) {
                    const existingPartyActions = data.partyActions || {};
                    const existingPlayerReactions = data.playerReactions || {};

                    if (data.status === 'PARTY_PHASE' || data.status === 'ACTIVE') {
                        if (!existingPartyActions[uid]) {
                            updatePayload[`partyActions.${uid}`] = { actionType: 'rejoin', success: false };
                            updatedData.partyActions = { ...existingPartyActions, [uid]: { actionType: 'rejoin', success: false } };
                        }
                    } else if (data.status === 'BOSS_PHASE') {
                        // Na fase do boss, só injeta reação se for alvo e ainda não reagiu
                        const bossAttack = data.currentBossAttack || {};
                        const targets = bossAttack.targetUids || [];
                        if (targets.includes(uid) && !existingPlayerReactions[uid]) {
                            updatePayload[`playerReactions.${uid}`] = { reaction: 'rejoin', success: false };
                            updatedData.playerReactions = { ...existingPlayerReactions, [uid]: { reaction: 'rejoin', success: false } };
                        }
                    }
                }

                transaction.update(raidRef, updatePayload);

                return { data: updatedData, isHost: data.hostUid === uid };
            });

            this.isHost = resultData.isHost;
            this.currentRaidData = resultData.data;
            this.startListener(raidId);
            return this.currentRaidData;
        } catch (e) {
            console.warn('[RaidRealtime] Erro na transação inicial, tentando sincronização direta:', e);
            try {
                // Tenta leitura direta sem transação antes de cair para local puro
                const raidRef = fbDB.collection('raids').doc(raidId);
                const snap = await raidRef.get();
                if (snap.exists) {
                    const data = snap.data();
                    const players = [...(data.players || [])];
                    const existingIndex = players.findIndex(p => p.uid === uid);
                    const avId = currentPlayerData.avatarId || '02';
                    const safePhoto = (currentPlayerData.photoURL && currentPlayerData.photoURL.startsWith('assets/avatars/')) 
                        ? currentPlayerData.photoURL 
                        : `assets/avatars/avatar_${avId}.png`;
                    const safeCurrent = { ...currentPlayerData, photoURL: safePhoto };

                    if (existingIndex >= 0) {
                        players[existingIndex] = { ...players[existingIndex], ...safeCurrent, lastActive: Date.now() };
                    } else if (players.length < 4) {
                        players.push({ ...safeCurrent, ready: false, combatStatus: 'ACTIVE', lastActive: Date.now() });
                    }
                    await raidRef.set({ ...data, players, updatedAt: firebase.firestore.FieldValue.serverTimestamp() }, { merge: true });
                    this.isHost = data.hostUid === uid;
                    this.currentRaidData = { ...data, players };
                    this.startListener(raidId);
                    return this.currentRaidData;
                }
            } catch (err2) {
                console.warn('[RaidRealtime] Fallback direto falhou, operando em modo local resiliente:', err2);
            }

            this.localMode = true;
            this.isHost = true;
            this.currentRaidData = this._createLocalRoomData(raidId, partyId, chapterId, currentPlayerData, bossData);
            return this.currentRaidData;
        }
    }

    _createLocalRoomData(raidId, partyId, chapterId, currentPlayerData, bossData) {
        return {
            id: raidId,
            partyId,
            chapterId,
            hostUid: currentPlayerData.uid,
            status: 'LOBBY',
            bossId: bossData.id,
            bossState: {
                ...bossData,
                currentHp: bossData.baseHp,
                maxHp: bossData.baseHp
            },
            players: [
                {
                    ...currentPlayerData,
                    ready: false,
                    combatStatus: 'ACTIVE',
                    lastActive: Date.now(),
                    damageDealt: 0,
                    damageTaken: 0,
                    healingDone: 0,
                    revivesCount: 0,
                    successfulActions: 0
                }
            ],
            turnState: {
                currentEntityId: null,
                round: 0,
                timeline: []
            },
            createdAt: Date.now(),
            startedAt: null,
            endedAt: null
        };
    }

    /**
     * Inicia o listener de snapshot do Firestore para sincronizar com todos da party
     */
    startListener(raidId) {
        this.stopListener();
        if (typeof fbDB === 'undefined') return;

        try {
            this.unsubRaidListener = fbDB.collection('raids').doc(raidId).onSnapshot({ includeMetadataChanges: true }, snap => {
                if (!snap.exists) return;

                // Ignora snapshots locais (cache otimista) — espera a confirmação do servidor.
                // Isso evita duplo-render no lobby e garante que o host veja o estado real.
                if (snap.metadata.hasPendingWrites) return;

                const data = snap.data() || {};
                if (data.players && Array.isArray(data.players)) {
                    data.players.forEach(p => {
                        const avId = p.avatarId || (p.photoURL && p.photoURL.match(/avatar_(\d+)\.png/) ? p.photoURL.match(/avatar_(\d+)\.png/)[1] : '02');
                        if (!p.photoURL || !p.photoURL.startsWith('assets/avatars/')) {
                            p.photoURL = `assets/avatars/avatar_${avId}.png`;
                        }
                    });
                }
                this.currentRaidData = { id: snap.id, ...data };
                if (this.onRaidUpdateCallback) {
                    this.onRaidUpdateCallback(this.currentRaidData);
                }
            }, err => {
                console.warn('[RaidRealtime] Snapshot listener erro:', err);
            });
        } catch (e) {
            console.warn('[RaidRealtime] Falha ao iniciar listener:', e);
        }
    }

    stopListener() {
        if (this.unsubRaidListener) {
            this.unsubRaidListener();
            this.unsubRaidListener = null;
        }
    }

    /**
     * Alterna o estado de Ready do jogador no Lobby
     */
    async toggleReady(uid) {
        if (!this.currentRaidData) return;
        const players = this.currentRaidData.players || [];
        const p = players.find(x => x.uid === uid);
        if (!p) return;

        p.ready = !p.ready;

        // Atualização Otimista Imediata da UI local
        if (this.onRaidUpdateCallback) {
            this.onRaidUpdateCallback(this.currentRaidData);
        }

        if (this.localMode || typeof fbDB === 'undefined' || !this.currentRaidId) {
            return;
        }

        try {
            await fbDB.collection('raids').doc(this.currentRaidId).update({
                players,
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            });
        } catch (e) {
            console.warn('[RaidRealtime] Erro ao sincronizar ready no Firestore:', e);
        }
    }

    /**
     * Troca o avatar do jogador no Lobby antes do início da batalha
     */
    async updatePlayerAvatar(uid, avatarId, avatarData, combatStats = null) {
        if (!this.currentRaidData || this.currentRaidData.status !== 'LOBBY') return;
        const players = this.currentRaidData.players || [];
        const p = players.find(x => x.uid === uid);
        if (!p) return;

        p.avatarId = avatarId;
        p.photoURL = `assets/avatars/avatar_${avatarId}.png`;
        p.avatarData = avatarData;
        if (combatStats) {
            Object.assign(p, combatStats);
        }

        if (this.localMode || typeof fbDB === 'undefined') {
            if (this.onRaidUpdateCallback) this.onRaidUpdateCallback(this.currentRaidData);
            return;
        }

        try {
            await fbDB.collection('raids').doc(this.currentRaidId).update({
                players,
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            });
        } catch (e) {
            console.warn('[RaidRealtime] Erro ao atualizar avatar:', e);
        }
    }

    /**
     * Envia a ação ofensiva ou de suporte do jogador na Fase da Party
     */
    async submitPlayerPartyAction(uid, actionData) {
        if (!this.currentRaidData) return;
        if (!this.currentRaidData.partyActions) {
            this.currentRaidData.partyActions = {};
        }
        this.currentRaidData.partyActions[uid] = actionData;

        // Disparo otimista local imediato para refletir na UI instantaneamente
        if (this.onRaidUpdateCallback) this.onRaidUpdateCallback(this.currentRaidData);

        if (this.localMode || typeof fbDB === 'undefined' || !this.currentRaidId) {
            return;
        }

        try {
            const cleanAction = this._sanitizeForFirestore(actionData);
            await fbDB.collection('raids').doc(this.currentRaidId).update({
                [`partyActions.${uid}`]: cleanAction,
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            });
        } catch (e) {
            console.warn('[RaidRealtime] Erro ao submeter ação da party:', e);
        }
    }

    /**
     * Envia a reação defensiva de um jogador (Esquiva, Contra-Golpe, Item)
     */
    async submitPlayerReaction(uid, reactionData) {
        if (!this.currentRaidData) return;
        if (!this.currentRaidData.playerReactions) {
            this.currentRaidData.playerReactions = {};
        }
        this.currentRaidData.playerReactions[uid] = reactionData;

        // Disparo otimista local imediato para refletir na UI instantaneamente
        if (this.onRaidUpdateCallback) this.onRaidUpdateCallback(this.currentRaidData);

        if (this.localMode || typeof fbDB === 'undefined' || !this.currentRaidId) {
            return;
        }

        try {
            const cleanReaction = this._sanitizeForFirestore(reactionData);
            await fbDB.collection('raids').doc(this.currentRaidId).update({
                [`playerReactions.${uid}`]: cleanReaction,
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            });
        } catch (e) {
            console.warn('[RaidRealtime] Erro ao submeter reação defensiva:', e);
        }
    }

    _sanitizeForFirestore(obj) {
        if (obj === null || obj === undefined) return null;
        try {
            return JSON.parse(JSON.stringify(obj, (k, v) => (v === undefined ? null : v)));
        } catch (e) {
            return obj;
        }
    }

    /**
     * Atualiza o estado da Raid (Autoritativo pelo Host)
     */
    async updateRaidState(partialState) {
        if (!this.currentRaidData) return;
        this.currentRaidData = { ...this.currentRaidData, ...partialState };

        if (this.localMode || typeof fbDB === 'undefined' || !this.currentRaidId) {
            if (this.onRaidUpdateCallback) this.onRaidUpdateCallback(this.currentRaidData);
            return;
        }

        try {
            const cleanState = this._sanitizeForFirestore(partialState);
            await fbDB.collection('raids').doc(this.currentRaidId).update({
                ...cleanState,
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            });
        } catch (e) {
            console.warn('[RaidRealtime] Erro ao atualizar estado da raid, tentando set merge:', e);
            try {
                const cleanState = this._sanitizeForFirestore(partialState);
                await fbDB.collection('raids').doc(this.currentRaidId).set({
                    ...cleanState,
                    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                }, { merge: true });
            } catch (errSet) {
                console.error('[RaidRealtime] Falha crítica ao persistir estado:', errSet);
            }
        }
    }

    /**
     * Sai da sala de Raid e limpa a sala se estiver vazia
     */
    async leaveRaid(uid) {
        this.stopListener();
        const raidId = this.currentRaidId;
        if (!raidId) return;

        if (!this.localMode && typeof fbDB !== 'undefined') {
            try {
                const raidRef = fbDB.collection('raids').doc(raidId);
                await fbDB.runTransaction(async (transaction) => {
                    const doc = await transaction.get(raidRef);
                    if (!doc.exists) return;

                    const data = doc.data();
                    const players = (data.players || []).filter(p => p.uid !== uid);

                    if (players.length === 0) {
                        // Se não restou nenhum jogador na sala, encerra e remove a sala
                        transaction.delete(raidRef);
                    } else {
                        let hostUid = data.hostUid;
                        if (hostUid === uid) {
                            hostUid = players[0].uid;
                        }
                        transaction.update(raidRef, {
                            players,
                            hostUid,
                            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                        });
                    }
                });
            } catch (e) {
                console.warn('[RaidRealtime] Notice ao sair da raid:', e);
            }
        }

        this.currentRaidId = null;
        this.currentRaidData = null;
    }
}

window.RaidRealtimeService = RaidRealtimeService;
window.raidRealtime = new RaidRealtimeService();


/* ═══ raid-audio.js ═══ */
/* ═══════════════════════════════════════════════════════════════
   CODE LEVELER — BOSS BATTLE RAIDS: AUDIO MANAGER
   Síntese sonora imersiva em tempo real com Web Audio API
   (Seção 20 de CODE_LEVELER_BOSS_BATTLE_RAIDS.md)
   ═══════════════════════════════════════════════════════════════ */

class RaidAudioManager {
    constructor() {
        this.ctx = null;
        this.enabled = true;
        this.bgMusicPlaying = false;
        this._bgMusicTimer = null;
        this._step = 0;
        this._tempo = 148; // BPM acelerado típico de Pokemon Gym / Elite 4
        this._bgGain = null;
        this._userGestureAttached = false;
    }

    init() {
        if (!this.ctx) {
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            if (AudioCtx) {
                this.ctx = new AudioCtx();
            }
        }
        if (this.ctx && this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }
        if (!this._userGestureAttached) {
            this._userGestureAttached = true;
            const unlock = () => {
                if (!this.ctx) {
                    this.init();
                }
                if (this.ctx && this.ctx.state === 'suspended') {
                    this.ctx.resume().catch(() => {});
                }
                if (this.bgMusicPlaying && this._bgMusicTimer === null) {
                    this._scheduleLoop();
                }
            };
            ['click', 'keydown', 'touchstart', 'touchend', 'pointerdown', 'mousedown'].forEach(evt => {
                window.addEventListener(evt, unlock, { passive: true });
                document.addEventListener(evt, unlock, { passive: true });
            });
        }
    }

    playTone(freq, duration = 0.1, type = 'sine', vol = 0.12) {
        if (!this.enabled) return;
        try {
            this.init();
            if (!this.ctx) return;
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();
            osc.type = type;
            osc.frequency.setValueAtTime(freq, this.ctx.currentTime);
            gain.gain.setValueAtTime(vol, this.ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.0001, this.ctx.currentTime + duration);
            osc.connect(gain);
            gain.connect(this.ctx.destination);
            osc.start();
            osc.stop(this.ctx.currentTime + duration);
        } catch (e) {}
    }

    playEvent(eventName) {
        if (!this.enabled) return;
        try {
            this.init();
            if (!this.ctx) return;
            const now = this.ctx.currentTime;

            switch (eventName) {
                case 'attack': {
                    // Efeito de corte veloz e impacto
                    const osc = this.ctx.createOscillator();
                    const gain = this.ctx.createGain();
                    osc.type = 'sawtooth';
                    osc.frequency.setValueAtTime(580, now);
                    osc.frequency.exponentialRampToValueAtTime(140, now + 0.18);
                    gain.gain.setValueAtTime(0.18, now);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
                    osc.connect(gain);
                    gain.connect(this.ctx.destination);
                    osc.start(now);
                    osc.stop(now + 0.18);
                    break;
                }
                case 'damage': {
                    // Impacto pesado e soco
                    const osc = this.ctx.createOscillator();
                    const gain = this.ctx.createGain();
                    osc.type = 'square';
                    osc.frequency.setValueAtTime(160, now);
                    osc.frequency.exponentialRampToValueAtTime(45, now + 0.22);
                    gain.gain.setValueAtTime(0.25, now);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.22);
                    osc.connect(gain);
                    gain.connect(this.ctx.destination);
                    osc.start(now);
                    osc.stop(now + 0.22);
                    break;
                }
                case 'counter': {
                    // Tinir metálico de contra-golpe (Parry)
                    this.playTone(880, 0.08, 'triangle', 0.20);
                    setTimeout(() => this.playTone(1320, 0.15, 'sine', 0.22), 40);
                    setTimeout(() => this.playTone(1760, 0.25, 'sine', 0.15), 90);
                    break;
                }
                case 'dodge': {
                    // Sopro de vento e teletransporte rápido
                    const osc = this.ctx.createOscillator();
                    const gain = this.ctx.createGain();
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(300, now);
                    osc.frequency.exponentialRampToValueAtTime(900, now + 0.15);
                    gain.gain.setValueAtTime(0.14, now);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
                    osc.connect(gain);
                    gain.connect(this.ctx.destination);
                    osc.start(now);
                    osc.stop(now + 0.15);
                    break;
                }
                case 'item': {
                    // Arpejo mágico de cura
                    [523.25, 659.25, 783.99, 1046.50].forEach((freq, i) => {
                        setTimeout(() => this.playTone(freq, 0.18, 'sine', 0.14), i * 65);
                    });
                    break;
                }
                case 'revive': {
                    // Ressonância de ressurreição celestial
                    [440, 554.37, 659.25, 880, 1108.73].forEach((freq, i) => {
                        setTimeout(() => this.playTone(freq, 0.35, 'triangle', 0.18), i * 90);
                    });
                    break;
                }
                case 'playerDown': {
                    // Queda sombria
                    const osc = this.ctx.createOscillator();
                    const gain = this.ctx.createGain();
                    osc.type = 'sawtooth';
                    osc.frequency.setValueAtTime(220, now);
                    osc.frequency.exponentialRampToValueAtTime(55, now + 0.45);
                    gain.gain.setValueAtTime(0.22, now);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.45);
                    osc.connect(gain);
                    gain.connect(this.ctx.destination);
                    osc.start(now);
                    osc.stop(now + 0.45);
                    break;
                }
                case 'bossDefeat': {
                    // Colapso massivo do chefe
                    const osc = this.ctx.createOscillator();
                    const gain = this.ctx.createGain();
                    osc.type = 'square';
                    osc.frequency.setValueAtTime(180, now);
                    osc.frequency.exponentialRampToValueAtTime(30, now + 0.85);
                    gain.gain.setValueAtTime(0.30, now);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.85);
                    osc.connect(gain);
                    gain.connect(this.ctx.destination);
                    osc.start(now);
                    osc.stop(now + 0.85);
                    break;
                }
                case 'victory': {
                    // Fanfarra triunfal
                    const notes = [
                        { f: 523.25, d: 150 },
                        { f: 659.25, d: 150 },
                        { f: 783.99, d: 150 },
                        { f: 1046.50, d: 450 }
                    ];
                    notes.forEach((n, idx) => {
                        setTimeout(() => this.playTone(n.f, n.d / 1000, 'triangle', 0.22), idx * 170);
                    });
                    break;
                }
                case 'miss': {
                    // Som oco de erro
                    this.playTone(180, 0.12, 'sawtooth', 0.12);
                    setTimeout(() => this.playTone(130, 0.18, 'sawtooth', 0.12), 100);
                    break;
                }
            }
        } catch (e) {}
    }

    /* ═══════════════════════════════════════════════════════════════
       BGM: TEMA GÓTICO & DRAMÁTICO DE BATALHA DE BOSS
       (Estilo Castlevania / Dark Souls / Órgão Arcano Sombrio)
       Sons:
       - Órgão de Tubos Gótico Polifônico (Sawtooth + Triangle com filtro ressonante)
       - Baixo Dramático Profundo (Sub-grave cavernoso)
       - Sino Gótico de Catedral (Frequências inarmônicas ressonantes)
       - Tímpanos / Bumbo de Marcha Imperial (Heavy war drums)
       ═══════════════════════════════════════════════════════════════ */

    getEffectiveBgmVolume() {
        if (window.soundFX && typeof window.soundFX.getEffectiveBgmVolume === 'function') {
            return window.soundFX.getEffectiveBgmVolume();
        }
        return 0.7;
    }

    applyVolumeSettings() {
        if (this._bgGain && this.ctx) {
            const baseVol = 0.22;
            const target = baseVol * this.getEffectiveBgmVolume();
            try {
                this._bgGain.gain.setValueAtTime(target, this.ctx.currentTime);
            } catch (e) {}
        }
    }

    startBattleMusic() {
        if (!this.enabled) return;
        this.init();
        if (this.bgMusicPlaying) return;
        this.bgMusicPlaying = true;
        this._step = 0;
        this._tempo = 126; // Andamento dramático, solene e imponente

        // Recria o _bgGain sempre para evitar nó desconectado de batalhas anteriores
        if (this.ctx) {
            if (this._bgGain) {
                try { this._bgGain.disconnect(); } catch (e) {}
            }
            this._bgGain = this.ctx.createGain();
            const baseVol = 0.22;
            const target = baseVol * this.getEffectiveBgmVolume();
            this._bgGain.gain.setValueAtTime(target, this.ctx.currentTime);
            this._bgGain.connect(this.ctx.destination);
        }

        // Se o ctx estiver suspenso (política de autoplay), agenda para depois do desbloqueio
        if (this.ctx && this.ctx.state === 'suspended') {
            this.ctx.resume().then(() => {
                if (this.bgMusicPlaying) this._scheduleLoop();
            }).catch(() => {});
        } else {
            this._scheduleLoop();
        }
    }

    stopBattleMusic() {
        this.bgMusicPlaying = false;
        if (this._bgMusicTimer) {
            clearTimeout(this._bgMusicTimer);
            this._bgMusicTimer = null;
        }
        if (this._bgGain && this.ctx) {
            try {
                this._bgGain.gain.setValueAtTime(this._bgGain.gain.value, this.ctx.currentTime);
                this._bgGain.gain.linearRampToValueAtTime(0.0001, this.ctx.currentTime + 0.4);
            } catch (e) {}
        }
    }

    /**
     * Toca uma nota de Órgão de Tubos Gótico (duas vozes ligeiramente desafinadas para calor e atmosfera sombria)
     */
    _playGothicOrgan(freq, dur, vol = 0.075, timeOffset = 0) {
        if (!this.ctx || !this.bgMusicPlaying || !freq) return;
        try {
            const start = this.ctx.currentTime + timeOffset;

            // Voz 1: Principal (sawtooth rica em harmônicos)
            const osc1 = this.ctx.createOscillator();
            const gain1 = this.ctx.createGain();
            const filter1 = this.ctx.createBiquadFilter();

            filter1.type = 'lowpass';
            filter1.frequency.setValueAtTime(1600, start);
            filter1.Q.setValueAtTime(3.5, start); // Ressonância mística

            osc1.type = 'sawtooth';
            osc1.frequency.setValueAtTime(freq, start);

            gain1.gain.setValueAtTime(0.001, start);
            gain1.gain.linearRampToValueAtTime(vol, start + 0.03); // Ataque de fole
            gain1.gain.exponentialRampToValueAtTime(0.0001, start + dur * 0.96);

            osc1.connect(filter1);
            filter1.connect(gain1);

            // Voz 2: Sub-oitava / ressonância mística (triangle com leve detune)
            const osc2 = this.ctx.createOscillator();
            const gain2 = this.ctx.createGain();
            osc2.type = 'triangle';
            osc2.frequency.setValueAtTime(freq * 0.5, start); // Oitava abaixo para peso catedral
            gain2.gain.setValueAtTime(vol * 0.5, start);
            gain2.gain.exponentialRampToValueAtTime(0.0001, start + dur * 0.94);

            osc2.connect(gain2);

            if (this._bgGain) {
                gain1.connect(this._bgGain);
                gain2.connect(this._bgGain);
            } else {
                gain1.connect(this.ctx.destination);
                gain2.connect(this.ctx.destination);
            }

            osc1.start(start);
            osc1.stop(start + dur);
            osc2.start(start);
            osc2.stop(start + dur);
        } catch (e) {}
    }

    /**
     * Baixo orquestral cavernoso (violoncelos e contrabaixos góticos)
     */
    _playGothicBass(freq, dur, vol = 0.12, timeOffset = 0) {
        if (!this.ctx || !this.bgMusicPlaying || !freq) return;
        try {
            const start = this.ctx.currentTime + timeOffset;
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();
            const filter = this.ctx.createBiquadFilter();

            filter.type = 'lowpass';
            filter.frequency.setValueAtTime(450, start);

            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(freq, start);

            gain.gain.setValueAtTime(vol, start);
            gain.gain.exponentialRampToValueAtTime(0.0001, start + dur * 0.98);

            osc.connect(filter);
            filter.connect(gain);

            if (this._bgGain) gain.connect(this._bgGain);
            else gain.connect(this.ctx.destination);

            osc.start(start);
            osc.stop(start + dur);
        } catch (e) {}
    }

    /**
     * Sino de Catedral Gótico (Toque sombrio da meia-noite)
     */
    _playCathedralBell(freq = 440, timeOffset = 0) {
        if (!this.ctx || !this.bgMusicPlaying) return;
        try {
            const start = this.ctx.currentTime + timeOffset;
            // Parcial harmônico metálico inarmônico típico de sino de bronze pesado
            const harmonics = [1, 2.76, 5.4, 8.93];
            harmonics.forEach((h, i) => {
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'sine';
                osc.frequency.setValueAtTime(freq * h, start);

                const dur = 1.6 / (i + 1);
                gain.gain.setValueAtTime(0.05 / (i + 1), start);
                gain.gain.exponentialRampToValueAtTime(0.0001, start + dur);

                osc.connect(gain);
                if (this._bgGain) gain.connect(this._bgGain);
                else gain.connect(this.ctx.destination);

                osc.start(start);
                osc.stop(start + dur);
            });
        } catch (e) {}
    }

    /**
     * Tímpano / Bumbo Orquestral de Batalha Épica
     */
    _playTimpani(timeOffset = 0) {
        if (!this.ctx || !this.bgMusicPlaying) return;
        try {
            const start = this.ctx.currentTime + timeOffset;
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();

            osc.type = 'sine';
            osc.frequency.setValueAtTime(120, start);
            osc.frequency.exponentialRampToValueAtTime(40, start + 0.18);

            gain.gain.setValueAtTime(0.24, start);
            gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.22);

            osc.connect(gain);
            if (this._bgGain) gain.connect(this._bgGain);
            else gain.connect(this.ctx.destination);

            osc.start(start);
            osc.stop(start + 0.23);
        } catch (e) {}
    }

    _scheduleLoop() {
        if (!this.bgMusicPlaying) return;
        if (this.ctx && this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }

        const stepDuration = 60 / (this._tempo * 2); // 1/8 note (~0.238s)

        // Escala Menor Harmônica Gótica em Ré (D Minor Harmonic)
        // D3, E3, F3, G3, A3, Bb3, C#4, D4, etc. (Tensão gótica clássica de órgão sacro)
        const D2 = 73.42, F2 = 87.31, G2 = 98.00, A2 = 110.00, Bb2 = 116.54, Cs3 = 138.59;
        const D3 = 146.83, E3 = 164.81, F3 = 174.61, G3 = 196.00, A3 = 220.00, Bb3 = 233.08, Cs4 = 277.18;
        const D4 = 293.66, E4 = 329.63, F4 = 349.23, G4 = 392.00, A4 = 440.00, Bb4 = 466.16, Cs5 = 554.37, D5 = 587.33, E5 = 659.25, F5 = 698.46;

        // Linha Baixa Dramática (Ostinato fúnebre / marcha de batalha gótica)
        const gothicBass = [
            D2, D2, D2, F2, D2, D2, A2, G2,
            D2, D2, D2, F2, D2, Cs3, D2, A2,
            Bb2, Bb2, Bb2, D3, Bb2, A2, A2, Cs3,
            D2, D2, F2, G2, A2, Cs3, D2, 0
        ];

        // Melodia de Órgão Gótico de Catedral (Harmônica Menor / Toccata)
        const organMelody = [
            D4,  0,   F4,  A4,  D5,  Cs5, D5,  A4,
            Bb4, A4,  G4,  F4,  E4,  F4,  Cs4, D4,
            F4,  0,   A4,  D5,  F5,  E5,  D5,  Cs5,
            D5,  A4,  F4,  D4,  Cs4, E4,  D4,  0
        ];

        const totalSteps = 32;
        const currentIdx = this._step % totalSteps;
        const bFreq = gothicBass[currentIdx];
        const mFreq = organMelody[currentIdx];

        // Toca Órgão de Tubos
        if (mFreq) {
            this._playGothicOrgan(mFreq, stepDuration * 1.15, 0.08);
        }

        // Toca Baixo Cavernoso
        if (bFreq) {
            this._playGothicBass(bFreq, stepDuration * 0.95, 0.12);
        }

        // Tímpano nos tempos fortes da marcha gótica
        if (currentIdx % 4 === 0) {
            this._playTimpani(0);
        } else if (currentIdx % 8 === 6) {
            this._playTimpani(stepDuration * 0.4);
        }

        // Sino de Catedral no primeiro compasso e na virada dramática
        if (currentIdx === 0) {
            this._playCathedralBell(D3, 0);
        } else if (currentIdx === 16) {
            this._playCathedralBell(A3, 0);
        }

        this._step++;

        this._bgMusicTimer = setTimeout(() => {
            this._scheduleLoop();
        }, stepDuration * 1000);
    }
}

window.raidAudio = new RaidAudioManager();


/* ═══ raid-animations.js ═══ */
/* ═══════════════════════════════════════════════════════════════
   CODE LEVELER — BOSS BATTLE RAIDS: ANIMATION CONTROLLER
   Sequências animadas de combate, dashes, tremores e números flutuantes
   (Seção 19 de CODE_LEVELER_BOSS_BATTLE_RAIDS.md)
   ═══════════════════════════════════════════════════════════════ */

class RaidAnimations {
    /**
     * Exibe número flutuante de dano, cura ou MISS sobre o elemento
     * Duração estendida para leitura confortável (2400ms)
     */
    static showFloatingText(targetEl, text, type = 'damage') {
        if (!targetEl) return;
        const rect = targetEl.getBoundingClientRect();

        const floatEl = document.createElement('div');
        floatEl.className = `raid-floating-text ${type}`;
        floatEl.textContent = text;

        // Posição no centro do elemento alvo com leve dispersão randômica
        const offsetX = (Math.random() - 0.5) * 24;
        const offsetY = (Math.random() - 0.5) * 12;
        floatEl.style.left = `${rect.left + rect.width / 2 + offsetX}px`;
        floatEl.style.top = `${rect.top + rect.height * 0.25 + offsetY}px`;

        document.body.appendChild(floatEl);

        setTimeout(() => {
            if (floatEl.parentNode) {
                floatEl.parentNode.removeChild(floatEl);
            }
        }, 2400);
    }

    /**
     * Gera partículas dinâmicas voando/saltando a partir do alvo atingido
     * Tipos: 'damage' (faíscas/brasas), 'crit' (estilhaços dourados), 'miss' (fagulhas azuis), 'heal' (orbes esmeralda)
     */
    static spawnImpactParticles(targetEl, type = 'damage', count = 14) {
        if (!targetEl) return;
        const rect = targetEl.getBoundingClientRect();
        const originX = rect.left + rect.width / 2;
        const originY = rect.top + rect.height * 0.4;

        const container = document.body;
        const particleCount = Math.min(24, Math.max(8, count));

        for (let i = 0; i < particleCount; i++) {
            const particle = document.createElement('div');
            particle.className = `raid-impact-particle ${type}`;

            // Vetor radial de explosão e dispersão
            const angle = Math.random() * Math.PI * 2;
            const distance = 40 + Math.random() * 80;
            const dx = Math.cos(angle) * distance;
            const dy = Math.sin(angle) * distance - (type === 'heal' ? 30 : 15); // cura sobe mais
            const rot = (Math.random() - 0.5) * 360;
            const scale = 0.6 + Math.random() * 0.8;
            const duration = 650 + Math.random() * 450;

            particle.style.left = `${originX}px`;
            particle.style.top = `${originY}px`;
            particle.style.setProperty('--dx', `${dx}px`);
            particle.style.setProperty('--dy', `${dy}px`);
            particle.style.setProperty('--rot', `${rot}deg`);
            particle.style.setProperty('--scale', scale);
            particle.style.animationDuration = `${duration}ms`;

            container.appendChild(particle);

            setTimeout(() => {
                if (particle.parentNode) {
                    particle.parentNode.removeChild(particle);
                }
            }, duration + 50);
        }
    }

    /**
     * Aplica breve impacto e flash de impacto na tela/arena
     */
    static triggerScreenImpact(intensity = 'medium') {
        const arena = document.getElementById('boss-raid-arena') || document.querySelector('.boss-raid-arena');
        if (arena) {
            arena.classList.remove('anim-arena-shake', 'anim-arena-shake-heavy');
            void arena.offsetWidth; // Força reflow
            arena.classList.add(intensity === 'heavy' ? 'anim-arena-shake-heavy' : 'anim-arena-shake');
            setTimeout(() => {
                arena.classList.remove('anim-arena-shake', 'anim-arena-shake-heavy');
            }, 450);
        }

        // Breve flash de impacto periférico
        const flash = document.createElement('div');
        flash.className = `raid-impact-flash ${intensity === 'heavy' ? 'crit' : 'standard'}`;
        document.body.appendChild(flash);
        setTimeout(() => {
            if (flash.parentNode) flash.parentNode.removeChild(flash);
        }, 320);
    }

    /**
     * Animação completa de ataque do jogador contra o Boss
     */
    static animatePlayerAttack(playerCardEl, bossArenaEl, damageAmount, isCrit = false) {
        return new Promise(resolve => {
            if (!playerCardEl || !bossArenaEl) {
                resolve();
                return;
            }

            // Som de ataque
            if (window.raidAudio) window.raidAudio.playEvent('attack');

            // 1. Dash de avanço do herói
            playerCardEl.classList.add('anim-hero-dash');

            setTimeout(() => {
                // 2. Impacto no Boss
                bossArenaEl.classList.add('anim-boss-hit');
                if (window.raidAudio) window.raidAudio.playEvent('damage');

                // 3. Efeito de Partículas e Tremor de Impacto
                this.spawnImpactParticles(bossArenaEl, isCrit ? 'crit' : 'damage', isCrit ? 20 : 14);
                this.triggerScreenImpact(isCrit ? 'heavy' : 'medium');

                // 4. Número flutuante de dano com duração estendida
                this.showFloatingText(bossArenaEl, `-${damageAmount}`, isCrit ? 'crit' : 'damage');

                setTimeout(() => {
                    bossArenaEl.classList.remove('anim-boss-hit');
                    playerCardEl.classList.remove('anim-hero-dash');
                    resolve();
                }, 400);
            }, 300);
        });
    }

    /**
     * Animação do Boss atacando os jogadores alvos sequencialmente
     */
    static animateBossAttack(bossArenaEl, targetEls = [], damages = []) {
        return new Promise(async resolve => {
            if (!bossArenaEl || targetEls.length === 0) {
                resolve();
                return;
            }

            for (let i = 0; i < targetEls.length; i++) {
                const targetEl = targetEls[i];
                const dmg = damages[i] || 0;

                await new Promise(r => {
                    // Avanço do Boss
                    bossArenaEl.classList.add('anim-boss-dash');
                    if (window.raidAudio) window.raidAudio.playEvent('attack');

                    setTimeout(() => {
                        // Impacto no jogador
                        if (targetEl) {
                            targetEl.classList.add('anim-target-hit');
                            if (window.raidAudio) window.raidAudio.playEvent('damage');
                            this.spawnImpactParticles(targetEl, 'damage', 12);
                            this.triggerScreenImpact('medium');
                            this.showFloatingText(targetEl, `-${dmg}`, 'damage');
                        }

                        setTimeout(() => {
                            if (targetEl) targetEl.classList.remove('anim-target-hit');
                            bossArenaEl.classList.remove('anim-boss-dash');
                            r();
                        }, 350);
                    }, 250);
                });
            }

            resolve();
        });
    }

    /**
     * Animação de MISS com partículas de desvio/deflexão
     */
    static animateMiss(targetEl) {
        if (window.raidAudio) window.raidAudio.playEvent('miss');
        this.spawnImpactParticles(targetEl, 'miss', 8);
        this.showFloatingText(targetEl, 'MISS', 'miss');
    }

    /**
     * Animação de Cura com partículas esmeralda
     */
    static animateHeal(targetEl, amount) {
        if (window.raidAudio) window.raidAudio.playEvent('item');
        if (targetEl) targetEl.classList.add('anim-target-heal');
        this.spawnImpactParticles(targetEl, 'heal', 10);
        this.showFloatingText(targetEl, `+${amount}`, 'heal');
        setTimeout(() => {
            if (targetEl) targetEl.classList.remove('anim-target-heal');
        }, 500);
    }

    /**
     * Animação de Reviver
     */
    static animateRevive(targetEl, amount) {
        if (window.raidAudio) window.raidAudio.playEvent('revive');
        if (targetEl) targetEl.classList.add('anim-target-revive');
        this.spawnImpactParticles(targetEl, 'heal', 18);
        this.showFloatingText(targetEl, `REVIVIDO (+${amount})`, 'revive');
        setTimeout(() => {
            if (targetEl) targetEl.classList.remove('anim-target-revive');
        }, 800);
    }
}

window.RaidAnimations = RaidAnimations;


